scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header4', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[1].checked == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_customFilter_list_listColumn_checkbox')[2].checked == true;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '금액'항목을 groupby 시킨다.
    //1. After executing the sample, make the 'Amount' item groupby.
    //Verify step 1. The 'Amount' item is groupby.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text()", "금액");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. groupby되어진 '금액'항목을 클릭하여 '1'값으로 필터링한다.
    //2. Click on the 'Amount' item in the groupby to filter by '1' value.
    //Verify step 2. Filtered by a value of '1'.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr').not('.w2grid_hidedRow').length == 3", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. '재조회'버튼을 클릭 후 '금액'항목의 필터를 클릭하여 '1'값 필터링이 유지되는지 확인한다.
    //3. Click the 'Redial' button and then click the filter in the 'Amount' field to see if the '1' value filtering is maintained.
    //Verify step 3. The groupby is released and the '1' value filtering of the 'Amount' item is maintained and shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header4_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 29-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
